'use client';
import { useState, useEffect } from "react";
import axios from "axios";
import Layout from "../../components/Layout";
import DataTable from "../../components/DataTableCompte";
import Cookies from "js-cookie";
import { useRouter } from "next/navigation";
import {jwtDecode} from "jwt-decode";

export default function Comptes() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [activeTab, setActiveTab] = useState("all"); // 'all', 'etudiant', 'encadrant', 'tuteur'
  const [isAuthorized, setIsAuthorized] = useState(false); // Store authorization state
  const router = useRouter();

  useEffect(() => {
    const token = Cookies.get("token"); // Use js-cookie to get the token

    if (!token || token === "undefined" || token === "null") {
      console.log("Aucun token trouvé ou token invalide.");
      Cookies.remove("token"); // Remove the invalid token if it exists
      router.push("/"); // Redirect to login page
      return;
    }

    try {
      const decodedToken = jwtDecode(token); // Decode the token
      console.log("Token décodé :", decodedToken);

      // Check if the user has the 'responsableFiliere' role
      if (decodedToken.role !== "responsableFiliere") {
        console.log("Accès refusé : rôle non autorisé.");
        Cookies.remove("token"); // Remove the token if the role is unauthorized
        router.push("/"); // Redirect to login page
        return;
      }

      console.log("Accès autorisé : utilisateur responsableFiliere.");
      setIsAuthorized(true);
    } catch (error) {
      console.log("Erreur lors du décodage du token :", error);
      Cookies.remove("token"); // Remove the invalid token if an error occurs
      router.push("/"); // Redirect to login page
    }
  }, [router]);

  const filteredUsers = () => {
    if (activeTab === "all") return users;
    return users.filter(user => user.role === activeTab);
  };




  const sendEmail = async (email, password) => {
    try {
      // Envoi uniquement des informations nécessaires (email et password)
      await axios.post("http://localhost:5000/api/send-email", {
        email,       // L'email du destinataire
        password,    // Le mot de passe pour l'utilisateur
      });
      alert(`Email envoyé avec succès à ${email}`);
    } catch (error) {
      alert(`Erreur lors de l'envoi de l'email à ${email}`);
      console.error("Erreur lors de l'envoi de l'email:", error);
    }
  };
  

  const sendEmailToSelected = async () => {
    try {
      for (const userId of selectedUsers) {
        const user = users.find((user) => user.id === userId);
        if (user) {
          await sendEmail(user.email, user.password);
        }
      }
      alert("Emails envoyés avec succès aux utilisateurs sélectionnés");
    } catch (error) {
      alert("Erreur lors de l'envoi des emails");
    }
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedUsers(filteredUsers().map((user) => user.id));
    } else {
      setSelectedUsers([]);
    }
  };

  const handleSelectUser = (userId) => {
    setSelectedUsers((prevState) =>
      prevState.includes(userId)
        ? prevState.filter((id) => id !== userId)
        : [...prevState, userId]
    );
  };

  const columns = [
    {
      header: "Sélectionner",
      accessor: "select",
      render: (user) => (
        <input
          type="checkbox"
          checked={selectedUsers.includes(user.id)}
          onChange={() => handleSelectUser(user.id)}
          className="form-checkbox h-5 w-5 text-blue-600 rounded"
        />
      ),
    },
    { header: "ID", accessor: "id" },
    { header: "ID user", accessor: "user_id" },
    { header: "Email", accessor: "email" },
    { header: "Mot de Passe", accessor: "password" },
    { header: "Rôle", accessor: "role" },
    {
      header: "Envoyer Email",
      accessor: "actions",
      render: (user) => (
        <button
          onClick={() => sendEmail(user.email, user.password)}
          className="text-indigo-600 hover:text-indigo-700 font-medium"
        >
          Envoyer Email
        </button>
      ),
    },
  ];

  if (loading) return <p className="text-center text-gray-500">Chargement en cours...</p>;
  if (error) return <p className="text-center text-red-500">{error}</p>;

  return (
    <Layout>
      <div className="w-full flex-1 py-3 px-4 overflow-hidden">
        <div className="flex justify-between items-center mb-4">
          <h1 className=" form-title text-3xl font-semibold text-gray-800 underline">Liste des comptes</h1>
          <button
            onClick={sendEmailToSelected}
            disabled={selectedUsers.length === 0}
            className={`bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition duration-300 shadow-md ${
              selectedUsers.length === 0 ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            Envoyer Email aux utilisateurs sélectionnés ({selectedUsers.length})
          </button>
        </div>

        {/* Role tabs */}
        <div className="flex mb-4 border-b border-gray-200">
          <button
            className={`py-2 px-4 font-medium ${activeTab === 'all' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
            onClick={() => setActiveTab('all')}
          >
            Tous
          </button>
          <button
            className={`py-2 px-4 font-medium ${activeTab === 'etudiant' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
            onClick={() => setActiveTab('etudiant')}
          >
            Étudiants
          </button>
          <button
            className={`py-2 px-4 font-medium ${activeTab === 'encadrant' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
            onClick={() => setActiveTab('encadrant')}
          >
            Encadrants
          </button>
          <button
            className={`py-2 px-4 font-medium ${activeTab === 'tuteur' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
            onClick={() => setActiveTab('tuteur')}
          >
            Tuteurs
          </button>
        </div>

        <div className="flex justify-between items-center mb-3">
          <div className="flex items-center space-x-3">
            <label className="inline-flex items-center">
              <input
                type="checkbox"
                onChange={handleSelectAll}
                checked={selectedUsers.length === filteredUsers().length && filteredUsers().length > 0}
                className="form-checkbox h-5 w-5 text-blue-600 rounded"
              />
              <span className="ml-2 text-lg text-gray-700">Sélectionner tout</span>
            </label>
          </div>
          {/* Ajouter ici la barre de recherche si nécessaire */}
        </div>

        <DataTable
          columns={columns}
          data={filteredUsers()}
          initialPage={1}
          initialItemsPerPage={10}
          sortable={true}
        />
      </div>
    </Layout>
  );
}